package autonewsroller.tts;

import autonewsroller.gpu.GpuLane;import autonewsroller.util.Json;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class QwenNarrator implements NarrationEngine {private final Path root;private final String url;public QwenNarrator(Path root,String url){this.root=root;this.url=url;}public String name(){return "Qwen3 fallback";}public NarrationResult narrate(String text,String voice,Path output)throws Exception{Files.createDirectories(output.getParent());Path txt=output.resolveSibling(output.getFileName()+".txt");Files.writeString(txt,text,StandardCharsets.UTF_8);try(GpuLane ignored=GpuLane.shared(root.resolve("output/runtime/gpu_ai_lane.lock"))){String py=Files.isRegularFile(root.resolve(".venv-qwen3-tts/Scripts/python.exe"))?root.resolve(".venv-qwen3-tts/Scripts/python.exe").toString():"python";ProcessBuilder b=new ProcessBuilder(py,root.resolve("tools/qwen3_tts.py").toString(),"--server",url,"--text-file",txt.toString(),"--output",output.toString(),"--voice",voice);ProcessRunner.run(b,600);}if(!Files.isRegularFile(output)||Files.size(output)==0)throw new IllegalStateException("Qwen3-TTS did not create WAV");Path meta=output.resolveSibling(output.getFileName()+".json");Map<String,Object>m=new LinkedHashMap<>();m.put("engine","Qwen3 fallback");m.put("voice",voice);m.put("wav",output.toString());Json.write(meta,m);System.out.println("TTS engine used: Qwen3 fallback");return new NarrationResult("Qwen3 fallback",voice,output,meta);}}
